-- Phase 12: vendor profiles, moderation, snapshots, append-only ledger, and payouts.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "VendorApplicationStatus" AS ENUM ('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED');
CREATE TYPE "VendorProductStatus" AS ENUM ('DRAFT','SUBMITTED','IN_REVIEW','CHANGES_REQUESTED','APPROVED','PUBLISHED','REJECTED','SUSPENDED');
CREATE TYPE "VendorMemberRole" AS ENUM ('VENDOR_OWNER','VENDOR_MANAGER','VENDOR_EDITOR','VENDOR_FINANCE');
CREATE TYPE "VendorPayoutStatus" AS ENUM ('REQUESTED','UNDER_REVIEW','APPROVED','PROCESSING','PAID','REJECTED','FAILED','CANCELLED');
CREATE TYPE "VendorLedgerEventType" AS ENUM ('SALE_CREDIT','PLATFORM_COMMISSION','REFUND_REVERSAL','PAYOUT_RESERVATION','PAYOUT_COMPLETION','PAYOUT_RELEASE','MANUAL_ADJUSTMENT');

ALTER TABLE "Template" ADD COLUMN "vendorId" UUID, ADD COLUMN "vendorStatus" "VendorProductStatus" NOT NULL DEFAULT 'APPROVED';
ALTER TABLE "OrderItem" ADD COLUMN "vendorId" UUID, ADD COLUMN "vendorNameSnapshot" TEXT, ADD COLUMN "commissionRateBpsSnapshot" INTEGER, ADD COLUMN "platformCommissionMmk" INTEGER, ADD COLUMN "vendorEarningMmk" INTEGER;
CREATE INDEX "Template_vendorId_vendorStatus_status_idx" ON "Template"("vendorId","vendorStatus","status");
CREATE INDEX "OrderItem_vendorId_createdAt_idx" ON "OrderItem"("vendorId","createdAt");

CREATE TABLE "VendorProfile" ("id" UUID NOT NULL,"ownerId" UUID NOT NULL,"storeName" TEXT NOT NULL,"storeSlug" TEXT NOT NULL,"storeDescription" TEXT NOT NULL,"contactEmail" TEXT NOT NULL,"portfolioUrl" TEXT,"logoStorageKey" TEXT,"bannerStorageKey" TEXT,"isVerified" BOOLEAN NOT NULL DEFAULT false,"isSuspended" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VendorProfile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "VendorProfile_storeSlug_key" ON "VendorProfile"("storeSlug");CREATE INDEX "VendorProfile_ownerId_isSuspended_idx" ON "VendorProfile"("ownerId","isSuspended");CREATE INDEX "VendorProfile_isVerified_isSuspended_idx" ON "VendorProfile"("isVerified","isSuspended");
CREATE TABLE "VendorApplication" ("id" UUID NOT NULL,"applicantId" UUID NOT NULL,"vendorId" UUID,"sellerType" TEXT NOT NULL,"storeName" TEXT NOT NULL,"storeSlug" TEXT NOT NULL,"storeDescription" TEXT NOT NULL,"contactEmail" TEXT NOT NULL,"portfolioUrl" TEXT,"businessInformation" TEXT,"verificationStorageKey" TEXT,"termsAcceptedAt" TIMESTAMP(3),"status" "VendorApplicationStatus" NOT NULL DEFAULT 'DRAFT',"reviewerId" UUID,"reviewerNote" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VendorApplication_pkey" PRIMARY KEY ("id"));
CREATE INDEX "VendorApplication_applicantId_status_createdAt_idx" ON "VendorApplication"("applicantId","status","createdAt");CREATE INDEX "VendorApplication_status_createdAt_idx" ON "VendorApplication"("status","createdAt");
CREATE TABLE "VendorMember" ("id" UUID NOT NULL,"vendorId" UUID NOT NULL,"userId" UUID NOT NULL,"role" "VendorMemberRole" NOT NULL,"invitedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"acceptedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),CONSTRAINT "VendorMember_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "VendorMember_vendorId_userId_key" ON "VendorMember"("vendorId","userId");CREATE INDEX "VendorMember_userId_revokedAt_idx" ON "VendorMember"("userId","revokedAt");
CREATE TABLE "VendorCommissionRule" ("id" UUID NOT NULL,"vendorId" UUID,"categoryId" UUID,"rateBps" INTEGER NOT NULL,"effectiveAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3),"reason" TEXT,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "VendorCommissionRule_pkey" PRIMARY KEY ("id"));CREATE INDEX "VendorCommissionRule_vendorId_effectiveAt_idx" ON "VendorCommissionRule"("vendorId","effectiveAt");CREATE INDEX "VendorCommissionRule_categoryId_effectiveAt_idx" ON "VendorCommissionRule"("categoryId","effectiveAt");
CREATE TABLE "VendorEarning" ("id" UUID NOT NULL,"vendorId" UUID NOT NULL,"orderItemId" UUID NOT NULL,"grossMmk" INTEGER NOT NULL,"platformCommissionMmk" INTEGER NOT NULL,"netMmk" INTEGER NOT NULL,"availableAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VendorEarning_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "VendorEarning_orderItemId_key" ON "VendorEarning"("orderItemId");CREATE INDEX "VendorEarning_vendorId_availableAt_createdAt_idx" ON "VendorEarning"("vendorId","availableAt","createdAt");
CREATE TABLE "VendorLedgerEntry" ("id" UUID NOT NULL,"vendorId" UUID NOT NULL,"earningId" UUID,"actorId" UUID,"eventType" "VendorLedgerEventType" NOT NULL,"amountMmk" INTEGER NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "VendorLedgerEntry_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "VendorLedgerEntry_idempotencyKey_key" ON "VendorLedgerEntry"("idempotencyKey");CREATE UNIQUE INDEX "VendorLedgerEntry_eventType_sourceType_sourceId_key" ON "VendorLedgerEntry"("eventType","sourceType","sourceId");CREATE INDEX "VendorLedgerEntry_vendorId_createdAt_idx" ON "VendorLedgerEntry"("vendorId","createdAt");
CREATE TABLE "VendorPayoutAccount" ("id" UUID NOT NULL,"vendorId" UUID NOT NULL,"method" TEXT NOT NULL,"accountName" TEXT NOT NULL,"accountNumber" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VendorPayoutAccount_pkey" PRIMARY KEY ("id"));CREATE INDEX "VendorPayoutAccount_vendorId_isActive_idx" ON "VendorPayoutAccount"("vendorId","isActive");
CREATE TABLE "VendorPayoutRequest" ("id" UUID NOT NULL,"vendorId" UUID NOT NULL,"accountId" UUID NOT NULL,"amountMmk" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'MMK',"status" "VendorPayoutStatus" NOT NULL DEFAULT 'REQUESTED',"idempotencyKey" TEXT NOT NULL,"reviewerId" UUID,"reviewerNote" TEXT,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reviewedAt" TIMESTAMP(3),"paidAt" TIMESTAMP(3),CONSTRAINT "VendorPayoutRequest_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "VendorPayoutRequest_idempotencyKey_key" ON "VendorPayoutRequest"("idempotencyKey");CREATE INDEX "VendorPayoutRequest_vendorId_status_requestedAt_idx" ON "VendorPayoutRequest"("vendorId","status","requestedAt");
CREATE TABLE "VendorPayoutTransaction" ("id" UUID NOT NULL,"payoutRequestId" UUID NOT NULL,"amountMmk" INTEGER NOT NULL,"method" TEXT NOT NULL,"transactionReference" TEXT,"confirmedById" UUID,"confirmedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "VendorPayoutTransaction_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "VendorPayoutTransaction_payoutRequestId_key" ON "VendorPayoutTransaction"("payoutRequestId");

ALTER TABLE "Template" ADD CONSTRAINT "Template_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "VendorProfile" ADD CONSTRAINT "VendorProfile_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "VendorApplication" ADD CONSTRAINT "VendorApplication_applicantId_fkey" FOREIGN KEY ("applicantId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "VendorApplication" ADD CONSTRAINT "VendorApplication_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "VendorApplication" ADD CONSTRAINT "VendorApplication_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "VendorMember" ADD CONSTRAINT "VendorMember_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "VendorMember" ADD CONSTRAINT "VendorMember_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "VendorCommissionRule" ADD CONSTRAINT "VendorCommissionRule_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "VendorCommissionRule" ADD CONSTRAINT "VendorCommissionRule_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "VendorCommissionRule" ADD CONSTRAINT "VendorCommissionRule_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "VendorEarning" ADD CONSTRAINT "VendorEarning_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "VendorEarning" ADD CONSTRAINT "VendorEarning_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "VendorLedgerEntry" ADD CONSTRAINT "VendorLedgerEntry_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "VendorLedgerEntry" ADD CONSTRAINT "VendorLedgerEntry_earningId_fkey" FOREIGN KEY ("earningId") REFERENCES "VendorEarning"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "VendorLedgerEntry" ADD CONSTRAINT "VendorLedgerEntry_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "VendorPayoutAccount" ADD CONSTRAINT "VendorPayoutAccount_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "VendorPayoutRequest" ADD CONSTRAINT "VendorPayoutRequest_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "VendorPayoutRequest" ADD CONSTRAINT "VendorPayoutRequest_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "VendorPayoutAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "VendorPayoutRequest" ADD CONSTRAINT "VendorPayoutRequest_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "VendorPayoutTransaction" ADD CONSTRAINT "VendorPayoutTransaction_payoutRequestId_fkey" FOREIGN KEY ("payoutRequestId") REFERENCES "VendorPayoutRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "VendorPayoutTransaction" ADD CONSTRAINT "VendorPayoutTransaction_confirmedById_fkey" FOREIGN KEY ("confirmedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

CREATE OR REPLACE FUNCTION nova_create_vendor_earnings() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE item_row RECORD; earning_id UUID;
BEGIN
  IF NEW.status = 'PAID' AND OLD.status IS DISTINCT FROM 'PAID' THEN
    FOR item_row IN SELECT "id","vendorId","unitPriceMmk","platformCommissionMmk","vendorEarningMmk" FROM "OrderItem" WHERE "orderId" = NEW."id" AND "vendorId" IS NOT NULL LOOP
      INSERT INTO "VendorEarning" ("id","vendorId","orderItemId","grossMmk","platformCommissionMmk","netMmk","availableAt","createdAt","updatedAt")
      VALUES (gen_random_uuid(),item_row."vendorId",item_row."id",item_row."unitPriceMmk",COALESCE(item_row."platformCommissionMmk",0),COALESCE(item_row."vendorEarningMmk",item_row."unitPriceMmk"),CURRENT_TIMESTAMP + interval '7 days',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
      ON CONFLICT ("orderItemId") DO NOTHING RETURNING "id" INTO earning_id;
      SELECT "id" INTO earning_id FROM "VendorEarning" WHERE "orderItemId"=item_row."id";
      INSERT INTO "VendorLedgerEntry" ("id","vendorId","earningId","eventType","amountMmk","sourceType","sourceId","idempotencyKey","createdAt") VALUES (gen_random_uuid(),item_row."vendorId",earning_id,'SALE_CREDIT',item_row."unitPriceMmk",'OrderItem',item_row."id",'sale:'||item_row."id",CURRENT_TIMESTAMP) ON CONFLICT ("idempotencyKey") DO NOTHING;
      INSERT INTO "VendorLedgerEntry" ("id","vendorId","earningId","eventType","amountMmk","sourceType","sourceId","idempotencyKey","createdAt") VALUES (gen_random_uuid(),item_row."vendorId",earning_id,'PLATFORM_COMMISSION',-COALESCE(item_row."platformCommissionMmk",0),'OrderItem',item_row."id",'commission:'||item_row."id",CURRENT_TIMESTAMP) ON CONFLICT ("idempotencyKey") DO NOTHING;
    END LOOP;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER nova_vendor_earnings_after_paid AFTER UPDATE OF "status" ON "Order" FOR EACH ROW EXECUTE FUNCTION nova_create_vendor_earnings();
